  "note" text NOT NULL DEFAULT '',
  "content" jsonb NOT NULL DEFAULT '{}',
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "published_at" timestamptz NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "intent_prompt_versions_provider_check" CHECK (provider = ANY (ARRAY['jev'::text, 'openai'::text])),
  CONSTRAINT "intent_prompt_versions_status_check" CHECK (status = ANY (ARRAY['draft'::text, 'published'::text, 'archived'::text])),
  CONSTRAINT "intent_prompt_versions_version_check" CHECK (version > 0)
);
-- create index "intent_prompt_versions_prompt_id_version_key" to table: "intent_prompt_versions"
CREATE UNIQUE INDEX "intent_prompt_versions_prompt_id_version_key" ON "intent_prompt_versions" ("prompt_id", "version");
-- create index "intent_prompt_versions_prompt_status" to table: "intent_prompt_versions"
