  "decision_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "intent_decision_snapshots_intent_decisions_intent_decision_snap" FOREIGN KEY ("decision_id") REFERENCES "intent_decisions" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);
-- create index "intent_decision_snapshots_decision_id_key" to table: "intent_decision_snapshots"
